/**
 * @param {null|boolean|number|string|Array|Object} o1
 * @param {null|boolean|number|string|Array|Object} o2
 * @return {boolean}
 */
var areDeeplyEqual = function(o1, o2) {
    // Identical primitives (or the very same reference) are equal
    if (o1 === o2) return true;

    // Past this point, anything that is not a non-null object can only be unequal
    // (typeof null === 'object', so null must be excluded explicitly)
    if (o1 === null || o2 === null || typeof o1 !== 'object' || typeof o2 !== 'object') {
        return false;
    }

    // An array is never equal to a plain object
    if (Array.isArray(o1) !== Array.isArray(o2)) return false;

    // Object.keys works for both arrays (indices) and objects (keys)
    const keys1 = Object.keys(o1);
    const keys2 = Object.keys(o2);
    if (keys1.length !== keys2.length) return false;

    for (const key of keys1) {
        // Same number of keys + every key of o1 present in o2 => same key set
        if (!Object.prototype.hasOwnProperty.call(o2, key)) return false;
        if (!areDeeplyEqual(o1[key], o2[key])) return false;
    }
    return true;
};
